import sys
from itertools import product

def findString(N, K):
    if N == 1:
        return ''.join(map(str, range(K)))
    edges = {}
    for comb in product(range(K), repeat=N):
        node = ''.join(map(str, comb[:-1]))
        edges[node] = ''.join(map(str, comb[1:]))
    path = []
    stack = [edges.keys()[0]]
    while stack:
        node = stack[-1]
        if node in edges:
            stack.append(edges[node])
            del edges[node]
        else:
            path.append(stack.pop())
    return path[-1] + path[-2][:-1]

input = sys.stdin.read().strip().split()
N = int(input[0])
K = int(input[1])
print(findString(N, K))
